screenPanels.initJs:
function(container, apiUrl, tables) {
  // テーブル再描画関数
  function renderOrders(orders) {
    const tbody = container.querySelector('#order-tbody');
    tbody.innerHTML = orders.map(order => `
      <tr data-id="${order.id || ''}">
        <td>${order.発注日 || order.orderDate || '-'}</td>
        <td>${order.顧客名 || order.customerName || '-'}</td>
        <td>${order.商品名 || order.productName || '-'}</td>
        <td>${order.数量 || order.quantity || 0}</td>
        <td>¥${(order.単価 || order.unitPrice || 0).toLocaleString()}</td>
        <td>¥${((order.数量 || order.quantity || 0) * (order.単価 || order.unitPrice || 0)).toLocaleString()}</td>
        <td><span class="px-2 py-1 rounded text-xs" style="background: rgba(34,197,94,0.1); color: #16a34a;">${order.ステータス || order.status || '-'}</span></td>
        <td>
          <button class="action-btn secondary edit-btn" data-id="${order.id || ''}" style="font-size: 12px; padding: 4px 8px;">編集</button>
          <button class="action-btn secondary delete-btn" data-id="${order.id || ''}" style="font-size: 12px; padding: 4px 8px;">削除</button>
        </td>
      </tr>
    `).join('');
  }

  // KPI更新関数
  function updateKPIs(orders, negotiations, monthlyData) {
    const totalOrders = orders.length;
    const totalAmount = orders.reduce((sum, o) => sum + ((o.数量 || o.quantity || 0) * (o.単価 || o.unitPrice || 0)), 0);
    const negotiationCount = negotiations.filter(n => (n.交渉ステータス || n.status) === '交渉中').length;
    const costReduction = monthlyData.reduce((sum, m) => sum + (m.コスト削減額 || m.costReduction || 0), 0);

    container.querySelector('#kpi-total-orders').textContent = totalOrders.toLocaleString();
    container.querySelector('#kpi-total-amount').textContent = `¥${totalAmount.toLocaleString()}`;
    container.querySelector('#kpi-negotiations').textContent = negotiationCount.toLocaleString();
    container.querySelector('#kpi-cost-reduction').textContent = `¥${costReduction.toLocaleString()}`;
  }

  // 月次グラフ初期化
  function initMonthlyChart(monthlyData) {
    const ctx = container.querySelector('#monthly-chart').getContext('2d');
    const labels = monthlyData.map(m => m.対象年月 || m.targetMonth || '');
    const amounts = monthlyData.map(m => m.発注金額合計 || m.totalAmount || 0);

    new Chart(ctx, {
      type: 'line',
      data: {
        labels: labels,
        datasets: [{
          label: '発注金額',
          data: amounts,
          borderColor: '#22c55e',
          backgroundColor: 'rgba(34,197,94,0.1)',
          tension: 0.4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          y: {
            beginAtZero: true,
            ticks: {
              callback: function(value) {
                return '¥' + value.toLocaleString();
              }
            }
          }
        }
      }
    });
  }

  // 価格分析グラフ初期化
  function initPriceAnalysisChart(analysisData) {
    const ctx = container.querySelector('#price-analysis-chart').getContext('2d');
    const labels = ['市場平均', '当社平均', '推奨価格'];
    const prices = [
      analysisData.reduce((sum, a) => sum + (a.市場平均単価 || a.marketAverage || 0), 0) / Math.max(analysisData.length, 1),
      analysisData.reduce((sum, a) => sum + (a.現在単価 || a.currentPrice || 0), 0) / Math.max(analysisData.length, 1),
      analysisData.reduce((sum, a) => sum + (a.推奨単価 || a.recommendedPrice || 0), 0) / Math.max(analysisData.length, 1)
    ];

    new Chart(ctx, {
      type: 'bar',
      data: {
        labels: labels,
        datasets: [{
          label: '価格比較',
          data: prices,
          backgroundColor: ['#ef4444', '#22c55e', '#3b82f6']
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          y: {
            beginAtZero: true,
            ticks: {
              callback: function(value) {
                return '¥' + value.toLocaleString();
              }
            }
          }
        }
      }
    });
  }

  // 初期データ表示
  const initialOrders = tables[0]?.records || [];
  const negotiations = tables[1]?.records || [];
  const monthlyData = tables[2]?.records || [];
  const analysisData = tables[4]?.records || [];

  renderOrders(initialOrders);
  updateKPIs(initialOrders, negotiations, monthlyData);

  // 交渉履歴サマリー更新
  const ongoingNegotiations = negotiations.filter(n => (n.交渉ステータス || n.status) === '交渉中').length;
  const monthlyAgreements = negotiations.filter(n => {
    const agreementDate = n.合意日時 || n.agreementDate || '';
    return agreementDate.includes(new Date().toISOString().slice(0, 7));
  }).length;

  container.querySelector('#ongoing-negotiations').textContent = ongoingNegotiations;
  container.querySelector('#monthly-agreements').textContent = monthlyAgreements;

  // 市場価格更新日
  const latestMarketData = tables[1]?.records?.[0];
  if (latestMarketData) {
    const updateDate = latestMarketData.価格取得日 || latestMarketData.priceDate || '';
    container.querySelector('#market-price-updated').textContent = updateDate.slice(0, 10);
  }

  // グラフ初期化
  if (monthlyData.length > 0) {
    initMonthlyChart(monthlyData);
  }
  if (analysisData.length > 0) {
    initPriceAnalysisChart(analysisData);
  }

  // 検索機能
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const customerKeyword = container.querySelector('#input-customer-search').value;
    const statusFilter = container.querySelector('#select-status-filter').value;
    const dateFrom = container.querySelector('#input-date-from').value;

    const allOrders = await window.aivicApi.list(0);
    if (!allOrders) return;

    const filtered = allOrders.filter(order => {
      const customerMatch = !customerKeyword || (order.顧客名 || order.customerName || '').includes(customerKeyword);
      const statusMatch = !statusFilter || (order.ステータス || order.status) === statusFilter;
      const dateMatch = !dateFrom || (order.発注日 || order.orderDate || '').startsWith(dateFrom);
      return customerMatch && statusMatch && dateMatch;
    });

    renderOrders(filtered);
  });

  // 新規発注モーダル制御
  const modal = container.querySelector('#new-order-modal');

  container.querySelector('#btn-new-order').addEventListener('click', () => {
    modal.style.display = 'flex';
  });

  container.querySelector('#btn-cancel-order').addEventListener('click', () => {
    modal.style.display = 'none';
  });

  // 新規発注保存
  container.querySelector('#btn-save-order').addEventListener('click', async () => {
    const customerName = container.querySelector('#input-customer-name').value;
    const productName = container.querySelector('#input-product-name').value;
    const quantity = parseInt(container.querySelector('#input-quantity').value);
    const unitPrice = parseInt(container.querySelector('#input-unit-price').value);
    const status = container.querySelector('#select-status').value;

    if (!customerName || !productName || !quantity || !unitPrice || !status) {
      alert('全ての項目を入力してください');
      return;
    }

    const orderData = {
      顧客名: customerName,
      商品名: productName,
      数量: quantity,
      単価: unitPrice,
      ステータス: status,
      発注日: new Date().toISOString().slice(0, 10),
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString()
    };

    const saved = await window.aivicApi.save(0, orderData);
    if (saved) {
      modal.style.display = 'none';
      // フォームリセット
      container.querySelector('#input-customer-name').value = '';
      container.querySelector('#input-product-name').value = '';
      container.querySelector('#input-quantity').value = '';
      container.querySelector('#input-unit-price').value = '';
      container.querySelector('#select-status').value = '';

      // 一覧更新
      const updatedOrders = await window.aivicApi.list(0);
      if (updatedOrders) {
        renderOrders(updatedOrders);
        updateKPIs(updatedOrders, negotiations, monthlyData);
      }
    }
  });

  // CSVエクスポート
  container.querySelector('#btn-export-csv').addEventListener('click', async () => {
    const allOrders = await window.aivicApi.list(0);
    if (!allOrders || allOrders.length === 0) {
      alert('エクスポートするデータがありません');
      return;
    }

    const headers = ['発注日', '顧客名', '商品名', '数量', '単価', '金額', 'ステータス'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...allOrders.map(order => [
        order.発注日 || order.orderDate || '',
        order.顧客名 || order.customerName || '',
        order.商品名 || order.productName || '',
        order.数量 || order.quantity || 0,
        order.単価 || order.unitPrice || 0,
        (order.数量 || order.quantity || 0) * (order.単価 || order.unitPrice || 0),
        order.ステータス || order.status || ''
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `発注データ_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
  });

  // 行レベル操作（編集・削除）
  container.addEventListener('click', async (e) => {
    const deleteBtn = e.target.closest('.delete-btn');
    const editBtn = e.target.closest('.edit-btn');

    if (deleteBtn) {
      if (!confirm('この発注データを削除しますか？')) return;

      const id = deleteBtn.dataset.id;
      await window.aivicApi.delete(0, id);

      const updatedOrders = await window.aivicApi.list(0);
      if (updatedOrders) {
        renderOrders(updatedOrders);
        updateKPIs(updatedOrders, negotiations, monthlyData);
      }
    }

    if (editBtn) {
      const id = editBtn.dataset.id;
      const allOrders = await window.aivicApi.list(0);
      const order = allOrders?.find(o => o.id === id);

      if (order) {
        container.querySelector('#input-customer-name').value = order.顧客名 || order.customerName || '';
        container.querySelector('#input-product-name').value = order.商品名 || order.productName || '';
        container.querySelector('#input-quantity').value = order.数量 || order.quantity || '';
        container.querySelector('#input-unit-price').value = order.単価 || order.unitPrice || '';
        container.querySelector('#select-status').value = order.ステータス || order.status || '';

        modal.style.display = 'flex';

        // 保存ボタンを更新モードに変更
        const saveBtn = container.querySelector('#btn-save-order');
        saveBtn.textContent = '更新';
        saveBtn.onclick = async () => {
          const updatedData = {
            顧客名: container.querySelector('#input-customer-name').value,
            商品名: container.querySelector('#input-product-name').value,
            数量: parseInt(container.querySelector('#input-quantity').value),
            単価: parseInt(container.querySelector('#input-unit-price').value),
            ステータス: container.querySelector('#select-status').value,
            更新日時: new Date().toISOString()
          };

          const updated = await window.aivicApi.update(0, id, updatedData);
          if (updated) {
            modal.style.display = 'none';
            saveBtn.textContent = '保存';
            saveBtn.onclick = null;

            const refreshedOrders = await window.aivicApi.list(0);
            if (refreshedOrders) {
              renderOrders(refreshedOrders);
              updateKPIs(refreshedOrders, negotiations, monthlyData);
            }
          }
        };
      }
    }
  });
}

function(container, apiUrl, tables) {
  let allNegotiations = tables[0].records || [];
  let selectedNegotiationId = null;

  // 1. 再描画関数の定義
  function renderRows(rows) {
    const tbody = container.querySelector("#negotiation-tbody");
    tbody.innerHTML = rows.map(r => {
      const reduction = (r.現在単価 && r.合意単価) ? r.現在単価 - r.合意単価 : 0;
      const statusClass = r.交渉ステータス === '合意' ? 'text-green-600' : 
                         r.交渉ステータス === '決裂' ? 'text-red-600' : 'text-yellow-600';
      return `
        <tr data-id="${r.交渉履歴ID}" class="hover:bg-main cursor-pointer border-b border-border">
          <td class="py-2 px-3 text-sm">${r.顧客名 || ''}</td>
          <td class="py-2 px-3 text-sm">${r.商品名 || ''}</td>
          <td class="py-2 px-3 text-sm">${r.交渉開始日 ? new Date(r.交渉開始日).toLocaleDateString() : ''}</td>
          <td class="py-2 px-3 text-sm">¥${(r.現在単価 || 0).toLocaleString()}</td>
          <td class="py-2 px-3 text-sm">¥${(r.提案単価 || 0).toLocaleString()}</td>
          <td class="py-2 px-3 text-sm">¥${(r.合意単価 || 0).toLocaleString()}</td>
          <td class="py-2 px-3 text-sm ${statusClass}">${r.交渉ステータス || ''}</td>
          <td class="py-2 px-3 text-sm ${reduction > 0 ? 'text-green-600' : ''}">¥${reduction.toLocaleString()}</td>
          <td class="py-2 px-3 text-sm">
            <button class="action-btn secondary edit-btn text-xs py-1 px-2" data-id="${r.交渉履歴ID}">編集</button>
            <button class="action-btn secondary delete-btn text-xs py-1 px-2 ml-1" data-id="${r.交渉履歴ID}">削除</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 2. 初期データ描画
  renderRows(allNegotiations);

  // KPI更新
  function updateKPIs(rows) {
    const successCount = rows.filter(r => r.交渉ステータス === '合意').length;
    const successRate = rows.length > 0 ? Math.round((successCount / rows.length) * 100) : 0;
    const avgReduction = rows.reduce((sum, r) => {
      const reduction = (r.現在単価 && r.合意単価) ? r.現在単価 - r.合意単価 : 0;
      return sum + reduction;
    }, 0) / (rows.length || 1);

    container.querySelector("#success-rate").textContent = successRate + '%';
    container.querySelector("#avg-reduction").textContent = '¥' + Math.round(avgReduction).toLocaleString();
    container.querySelector("#monthly-count").textContent = rows.length + '件';
  }
  updateKPIs(allNegotiations);

  // グラフ描画
  function drawPriceTrendChart() {
    const canvas = container.querySelector("#price-trend-chart");
    const ctx = canvas.getContext("2d");
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // サンプルデータでトレンドライン描画
    const data = [120000, 115000, 110000, 108000, 105000];
    const maxPrice = Math.max(...data);
    const minPrice = Math.min(...data);
    const range = maxPrice - minPrice;

    ctx.strokeStyle = '#22c55e';
    ctx.lineWidth = 2;
    ctx.beginPath();

    data.forEach((price, i) => {
      const x = (i / (data.length - 1)) * (canvas.width - 40) + 20;
      const y = canvas.height - 20 - ((price - minPrice) / range) * (canvas.height - 40);
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '10px sans-serif';
    ctx.fillText('¥' + minPrice.toLocaleString(), 5, canvas.height - 5);
    ctx.fillText('¥' + maxPrice.toLocaleString(), 5, 15);
  }

  function drawMarketComparisonChart() {
    const canvas = container.querySelector("#market-comparison-chart");
    const ctx = canvas.getContext("2d");
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 棒グラフ
    const ourPrice = 105000;
    const marketPrice = 120000;
    const maxPrice = Math.max(ourPrice, marketPrice);

    const barWidth = 40;
    const ourHeight = (ourPrice / maxPrice) * (canvas.height - 40);
    const marketHeight = (marketPrice / maxPrice) * (canvas.height - 40);

    // 自社価格
    ctx.fillStyle = '#22c55e';
    ctx.fillRect(50, canvas.height - 20 - ourHeight, barWidth, ourHeight);

    // 市場価格
    ctx.fillStyle = '#ef4444';
    ctx.fillRect(120, canvas.height - 20 - marketHeight, barWidth, marketHeight);

    // ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '10px sans-serif';
    ctx.fillText('自社', 55, canvas.height - 5);
    ctx.fillText('市場', 125, canvas.height - 5);
  }

  drawPriceTrendChart();
  drawMarketComparisonChart();

  // 3. 検索機能
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const customer = container.querySelector("#customer-filter").value;
    const category = container.querySelector("#category-filter").value;
    const status = container.querySelector("#status-filter").value;
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;

    const rows = await window.aivicApi.list(0);
    if (!rows) return;

    const filtered = rows.filter(r => {
      if (customer && !r.顧客名?.includes(customer)) return false;
      if (category && !r.商品カテゴリ?.includes(category)) return false;
      if (status && r.交渉ステータス !== status) return false;
      if (startDate && new Date(r.交渉開始日) < new Date(startDate)) return false;
      if (endDate && new Date(r.交渉開始日) > new Date(endDate)) return false;
      return true;
    });

    renderRows(filtered);
    updateKPIs(filtered);
  });

  // 4. 新規登録モーダル
  const modal = container.querySelector("#add-modal");

  container.querySelector("#btn-add").addEventListener("click", () => {
    modal.style.display = "flex";
  });

  container.querySelector("#modal-cancel").addEventListener("click", () => {
    modal.style.display = "none";
  });

  container.querySelector("#modal-save").addEventListener("click", async () => {
    const customer = container.querySelector("#modal-customer").value;
    const product = container.querySelector("#modal-product").value;
    const currentPrice = parseInt(container.querySelector("#modal-current-price").value) || 0;
    const proposedPrice = parseInt(container.querySelector("#modal-proposed-price").value) || 0;
    const reason = container.querySelector("#modal-reason").value;
    const content = container.querySelector("#modal-content").value;

    if (!customer || !product) {
      alert("顧客と商品名は必須です");
      return;
    }

    const newRecord = {
      顧客名: customer,
      商品名: product,
      交渉開始日: new Date().toISOString(),
      現在単価: currentPrice,
      提案単価: proposedPrice,
      交渉ステータス: "交渉中",
      交渉理由: reason,
      交渉内容: content,
      営業担当者ID: "user-001"
    };

    const saved = await window.aivicApi.save(0, newRecord);
    if (saved) {
      modal.style.display = "none";
      const rows = await window.aivicApi.list(0);
      if (rows) {
        allNegotiations = rows;
        renderRows(rows);
        updateKPIs(rows);
      }
      // フォームクリア
      container.querySelector("#modal-customer").value = "";
      container.querySelector("#modal-product").value = "";
      container.querySelector("#modal-current-price").value = "";
      container.querySelector("#modal-proposed-price").value = "";
      container.querySelector("#modal-reason").value = "";
      container.querySelector("#modal-content").value = "";
    }
  });

  // 5. 行レベル操作（削除・編集・選択）
  container.addEventListener("click", async (e) => {
    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      if (!confirm("この交渉履歴を削除しますか？")) return;
      await window.aivicApi.delete(0, deleteBtn.dataset.id);
      const rows = await window.aivicApi.list(0);
      if (rows) {
        allNegotiations = rows;
        renderRows(rows);
        updateKPIs(rows);
      }
      return;
    }

    const editBtn = e.target.closest(".edit-btn");
    if (editBtn) {
      const negotiation = allNegotiations.find(n => n.交渉履歴ID === editBtn.dataset.id);
      if (negotiation) {
        container.querySelector("#modal-customer").value = negotiation.顧客名 || "";
        container.querySelector("#modal-product").value = negotiation.商品名 || "";
        container.querySelector("#modal-current-price").value = negotiation.現在単価 || "";
        container.querySelector("#modal-proposed-price").value = negotiation.提案単価 || "";
        container.querySelector("#modal-reason").value = negotiation.交渉理由 || "";
        container.querySelector("#modal-content").value = negotiation.交渉内容 || "";
        modal.style.display = "flex";
      }
      return;
    }

    // 行選択
    const row = e.target.closest("tr[data-id]");
    if (row) {
      selectedNegotiationId = row.dataset.id;
      // 選択状態の視覚化
      container.querySelectorAll("tr[data-id]").forEach(r => r.classList.remove("bg-primary/10"));
      row.classList.add("bg-primary/10");
    }
  });

  // 価格計算機
  container.querySelector("#btn-calculate").addEventListener("click", () => {
    const current = parseFloat(container.querySelector("#calc-current").value) || 0;
    const reduction = parseFloat(container.querySelector("#calc-reduction").value) || 0;
    const proposed = current * (1 - reduction / 100);
    container.querySelector("#calc-proposed").value = Math.round(proposed);
  });

  // CSVエクスポート
  container.querySelector("#btn-export").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(0);
    if (!rows) return;

    const headers = ["顧客名", "商品名", "交渉開始日", "現在単価", "提案単価", "合意単価", "交渉ステータス", "交渉理由"];
    const csvContent = "\uFEFF" + [
      headers.join(","),
      ...rows.map(r => [
        r.顧客名 || "",
        r.商品名 || "",
        r.交渉開始日 ? new Date(r.交渉開始日).toLocaleDateString() : "",
        r.現在単価 || "",
        r.提案単価 || "",
        r.合意単価 || "",
        r.交渉ステータス || "",
        r.交渉理由 || ""
      ].map(field => `"${field}"`).join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "negotiation_history.csv";
    link.click();
  });

  // 画面遷移ボタン
  container.querySelector("#btn-order-data").addEventListener("click", () => {
    window.showScreen("scr-1780317810582");
  });

  container.querySelector("#btn-factor-analysis").addEventListener("click", () => {
    window.showScreen("scr-1780317855900");
  });

  container.querySelector("#btn-price-comparison").addEventListener("click", () => {
    window.showScreen("scr-1780317880614");
  });
}

function(container, apiUrl, tables) {
  // 再描画関数の定義
  function renderOrderData(rows) {
    const tbody = container.querySelector("#order-data-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.集計ID || ''}">
        <td>${r.顧客名 || '-'}</td>
        <td>${r.商品カテゴリ || '-'}</td>
        <td>${(r.発注件数 || 0).toLocaleString()}件</td>
        <td>¥${(r.発注金額合計 || 0).toLocaleString()}</td>
        <td>¥${(r.平均発注単価 || 0).toLocaleString()}</td>
        <td>¥${(r.市場価格 || 0).toLocaleString()}</td>
        <td>${r.市場価格との乖離率 || 0}%</td>
        <td><span class="px-2 py-1 text-xs rounded" style="background: rgba(34,197,94,0.1); color: #22c55e;">${r.価格ランク || '標準'}</span></td>
        <td>${r.推奨アクション || '現状維持'}</td>
      </tr>
    `).join("");
  }

  function renderPriceComparison(rows) {
    const tbody = container.querySelector("#price-comparison-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.分析結果ID || ''}">
        <td>${r.顧客名 || '-'}</td>
        <td>${r.商品名 || '-'}</td>
        <td>¥${(r.顧客単価 || 0).toLocaleString()}</td>
        <td>¥${(r.市場平均単価 || 0).toLocaleString()}</td>
        <td>¥${(r.全顧客平均単価 || 0).toLocaleString()}</td>
        <td>${r.市場比較率 || 0}%</td>
        <td><span class="px-2 py-1 text-xs rounded" style="background: rgba(59,130,246,0.1); color: #3b82f6;">${r.価格ランク || '標準価格帯'}</span></td>
        <td>¥${(r.価格改善余地 || 0).toLocaleString()}</td>
        <td>${r.推奨アクション || '現状維持'}</td>
      </tr>
    `).join("");
  }

  function updateKPIs(monthlyData) {
    if (monthlyData.length > 0) {
      const totalOrders = monthlyData.reduce((sum, r) => sum + (r.発注件数 || 0), 0);
      const totalAmount = monthlyData.reduce((sum, r) => sum + (r.発注金額合計 || 0), 0);
      const avgPrice = totalOrders > 0 ? Math.round(totalAmount / totalOrders) : 0;
      const avgDiff = monthlyData.reduce((sum, r) => sum + (r.市場価格との乖離率 || 0), 0) / monthlyData.length;

      container.querySelector("#kpi-order-count").textContent = totalOrders.toLocaleString() + "件";
      container.querySelector("#kpi-order-amount").textContent = "¥" + totalAmount.toLocaleString();
      container.querySelector("#kpi-avg-price").textContent = "¥" + avgPrice.toLocaleString();
      container.querySelector("#kpi-market-diff").textContent = avgDiff.toFixed(1) + "%";
    }
  }

  function drawTrendChart() {
    const canvas = container.querySelector("#trend-chart");
    const ctx = canvas.getContext("2d");

    // チャート背景をクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // サンプルデータ
    const months = ["10月", "11月", "12月", "1月", "2月", "3月"];
    const amounts = [1200000, 1350000, 1180000, 1420000, 1380000, 1450000];

    const padding = 40;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 軸を描画
    ctx.strokeStyle = '#6b7280';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // データ線を描画
    ctx.strokeStyle = '#22c55e';
    ctx.lineWidth = 2;
    ctx.beginPath();

    const maxAmount = Math.max(...amounts);
    const minAmount = Math.min(...amounts);
    const range = maxAmount - minAmount;

    amounts.forEach((amount, i) => {
      const x = padding + (i / (amounts.length - 1)) * chartWidth;
      const y = canvas.height - padding - ((amount - minAmount) / range) * chartHeight;

      if (i === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    });
    ctx.stroke();

    // データポイントを描画
    ctx.fillStyle = '#22c55e';
    amounts.forEach((amount, i) => {
      const x = padding + (i / (amounts.length - 1)) * chartWidth;
      const y = canvas.height - padding - ((amount - minAmount) / range) * chartHeight;

      ctx.beginPath();
      ctx.arc(x, y, 3, 0, 2 * Math.PI);
      ctx.fill();
    });

    // 月ラベルを描画
    ctx.fillStyle = '#9ca3af';
    ctx.font = '10px sans-serif';
    ctx.textAlign = 'center';
    months.forEach((month, i) => {
      const x = padding + (i / (months.length - 1)) * chartWidth;
      ctx.fillText(month, x, canvas.height - 10);
    });
  }

  function drawCategoryChart() {
    const canvas = container.querySelector("#category-chart");
    const ctx = canvas.getContext("2d");

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const categories = ["電子部品", "機械部品", "化学材料", "工具類"];
    const values = [35, 28, 22, 15];
    const colors = ['#22c55e', '#3b82f6', '#f59e0b', '#ef4444'];

    const centerX = canvas.width / 2;
    const centerY = canvas.height / 2;
    const radius = 60;

    let currentAngle = -Math.PI / 2;

    values.forEach((value, i) => {
      const sliceAngle = (value / 100) * 2 * Math.PI;

      ctx.fillStyle = colors[i];
      ctx.beginPath();
      ctx.moveTo(centerX, centerY);
      ctx.arc(centerX, centerY, radius, currentAngle, currentAngle + sliceAngle);
      ctx.closePath();
      ctx.fill();

      // ラベル描画
      const labelAngle = currentAngle + sliceAngle / 2;
      const labelX = centerX + Math.cos(labelAngle) * (radius + 20);
      const labelY = centerY + Math.sin(labelAngle) * (radius + 20);

      ctx.fillStyle = '#9ca3af';
      ctx.font = '10px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(categories[i], labelX, labelY);
      ctx.fillText(value + '%', labelX, labelY + 12);

      currentAngle += sliceAngle;
    });
  }

  function updatePriceStrategyResults(data) {
    const container_elem = container.querySelector("#price-strategy-results");
    if (data.length > 0) {
      const latest = data[0];
      container_elem.innerHTML = `
        <div class="space-y-2">
          <div class="flex justify-between text-xs">
            <span style="color: var(--text-muted);">推奨単価:</span>
            <span style="color: var(--text);">¥${(latest.推奨単価 || 0).toLocaleString()}</span>
          </div>
          <div class="flex justify-between text-xs">
            <span style="color: var(--text-muted);">価格競争力指数:</span>
            <span style="color: var(--text);">${latest.価格競争力指数 || 0}</span>
          </div>
          <div class="flex justify-between text-xs">
            <span style="color: var(--text-muted);">戦略区分:</span>
            <span style="color: var(--text);">${latest.戦略区分 || 'コスト戦略'}</span>
          </div>
          <div class="flex justify-between text-xs">
            <span style="color: var(--text-muted);">実施推奨度:</span>
            <span style="color: var(--text);">${latest.実施推奨度 || '高'}</span>
          </div>
        </div>
      `;
    }
  }

  // 初期データ描画
  if (tables[2] && tables[2].records) {
    renderOrderData(tables[2].records);
    updateKPIs(tables[2].records);
  }

  if (tables[5] && tables[5].records) {
    renderPriceComparison(tables[5].records);
  }

  if (tables[4] && tables[4].records) {
    updatePriceStrategyResults(tables[4].records);
  }

  // チャート描画
  setTimeout(() => {
    drawTrendChart();
    drawCategoryChart();
  }, 100);

  // 分析実行ボタン
  container.querySelector("#btn-analyze").addEventListener("click", async () => {
    const customerId = container.querySelector("#customer-select").value;
    const targetMonth = container.querySelector("#target-month").value;
    const category = container.querySelector("#category-select").value;

    // 月次集計結果を取得・フィルタリング
    const monthlyData = await window.aivicApi.list(2);
    if (monthlyData) {
      let filteredData = monthlyData;

      if (customerId) {
        filteredData = filteredData.filter(r => r.顧客ID === customerId);
      }
      if (targetMonth) {
        filteredData = filteredData.filter(r => r.対象年月 === targetMonth);
      }
      if (category) {
        filteredData = filteredData.filter(r => r.商品カテゴリ === category);
      }

      renderOrderData(filteredData);
      updateKPIs(filteredData);
    }

    // 価格比較分析結果を取得・更新
    const priceComparisonData = await window.aivicApi.list(5);
    if (priceComparisonData) {
      let filteredComparison = priceComparisonData;

      if (customerId) {
        filteredComparison = filteredComparison.filter(r => r.顧客ID === customerId);
      }

      renderPriceComparison(filteredComparison);
    }

    // 価格戦略分析結果を更新
    const strategyData = await window.aivicApi.list(4);
    if (strategyData) {
      updatePriceStrategyResults(strategyData);
    }

    // チャートを再描画
    drawTrendChart();
    drawCategoryChart();
  });

  // CSV出力ボタン
  container.querySelector("#btn-export").addEventListener("click", async () => {
    const data = await window.aivicApi.list(2);
    if (data) {
      const headers = ["顧客名", "商品カテゴリ", "発注件数", "発注金額合計", "平均発注単価", "市場価格との乖離率", "推奨アクション"];
      const csvContent = "\uFEFF" + [
        headers.join(","),
        ...data.map(r => [
          r.顧客名 || "",
          r.商品カテゴリ || "",
          r.発注件数 || 0,
          r.発注金額合計 || 0,
          r.平均発注単価 || 0,
          r.市場価格との乖離率 || 0,
          r.推奨アクション || ""
        ].join(","))
      ].join("\n");

      const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = "顧客別発注データ分析_" + new Date().toISOString().slice(0, 10) + ".csv";
      link.click();
    }
  });

  // トレンドチャートCSV出力
  container.querySelector("[data-testid='export-trend-button']").addEventListener("click", () => {
    const headers = ["月", "発注金額"];
    const months = ["2023-10", "2023-11", "2023-12", "2024-01", "2024-02", "2024-03"];
    const amounts = [1200000, 1350000, 1180000, 1420000, 1380000, 1450000];

    const csvContent = "\uFEFF" + [
      headers.join(","),
      ...months.map((month, i) => [month, amounts[i]].join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "発注金額推移_" + new Date().toISOString().slice(0, 10) + ".csv";
    link.click();
  });
}

function(container, apiUrl, tables) {
