  // 成功率推移グラフの描画
  function drawSuccessTrendChart() {
    const canvas = container.querySelector('#success-trend-chart');
    const ctx = canvas.getContext('2d');

    // キャンバスクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // データ
    const months = ['1月', '2月', '3月', '4月', '5月', '6月'];
    const successRates = [58, 62, 65, 61, 68, 63];
    const negotiationCounts = [45, 52, 48, 56, 51, 48];

    const padding = 40;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 軸の描画
    ctx.strokeStyle = '#e5e7eb';
    ctx.lineWidth = 1;

    // Y軸（左：成功率）
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.stroke();

    // Y軸（右：件数）
    ctx.beginPath();
    ctx.moveTo(canvas.width - padding, padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // X軸
    ctx.beginPath();
    ctx.moveTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // 成功率ライン
    ctx.strokeStyle = '#22c55e';
    ctx.lineWidth = 2;
    ctx.beginPath();

    successRates.forEach((rate, i) => {
      const x = padding + (chartWidth / (successRates.length - 1)) * i;
      const y = canvas.height - padding - (rate - 50) / 30 * chartHeight;

      if (i === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }

      // ポイント
      ctx.fillStyle = '#22c55e';
      ctx.beginPath();
      ctx.arc(x, y, 3, 0, Math.PI * 2);
      ctx.fill();
    });
    ctx.stroke();

    // 件数バー
    negotiationCounts.forEach((count, i) => {
      const x = padding + (chartWidth / negotiationCounts.length) * i + 10;
      const barWidth = chartWidth / negotiationCounts.length - 20;
      const barHeight = (count / 60) * chartHeight;

      ctx.fillStyle = 'rgba(245, 158, 11, 0.6)';
      ctx.fillRect(x, canvas.height - padding - barHeight, barWidth, barHeight);
    });

    // ラベル
    ctx.fillStyle = '#6b7280';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'center';

    months.forEach((month, i) => {
      const x = padding + (chartWidth / (months.length - 1)) * i;
      ctx.fillText(month, x, canvas.height - 10);
    });
  }

  // タイミング分析チャートの描画
  function drawTimingChart() {
    const canvas = container.querySelector('#timing-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const data = [
      { label: '月初', success: 72, total: 45 },
      { label: '月中', success: 58, total: 38 },
      { label: '月末', success: 45, total: 52 },
      { label: '四半期末', success: 68, total: 28 }
    ];

    const padding = 30;
    const barWidth = 60;
    const maxHeight = canvas.height - padding * 2;

    data.forEach((item, i) => {
      const x = padding + i * (barWidth + 20);
      const successHeight = (item.success / 100) * maxHeight;

      // 成功率バー
      ctx.fillStyle = '#22c55e';
      ctx.fillRect(x, canvas.height - padding - successHeight, barWidth, successHeight);

      // ラベル
      ctx.fillStyle = '#6b7280';
      ctx.font = '11px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(item.label, x + barWidth/2, canvas.height - 5);

      // 数値
      ctx.fillStyle = '#374151';
      ctx.fillText(item.success + '%', x + barWidth/2, canvas.height - padding - successHeight - 5);
    });
  }

  // 顧客別ランキングの再描画
  function renderCustomerRanking(data) {
    const tbody = container.querySelector('#customer-ranking-tbody');
    tbody.innerHTML = data.map((item, index) => `
