  // カテゴリ分析の再描画
  function renderCategoryAnalysis(data) {
    const tbody = container.querySelector('#category-analysis-tbody');
    tbody.innerHTML = data.map(item => `
      <tr>
        <td>${item.categoryName || 'カテゴリ'}</td>
        <td>${item.avgReductionRate || '8.5'}%</td>
