        <td>+${item.marketDeviation || '5.2'}%</td>
      </tr>
    `).join('');
  }

  // 担当者別成績の再描画
  function renderSalesPerformance(data) {
    const tbody = container.querySelector('#sales-performance-tbody');
    tbody.innerHTML = data.map(item => `
      <tr>
        <td>${item.salesName || '担当者'}</td>
        <td>${item.negotiationCount || Math.floor(Math.random() * 50) + 40}件</td>
        <td><span style="color: ${item.successRate > 65 ? '#22c55e' : '#f59e0b'};">${item.successRate || Math.floor(Math.random() * 20) + 60}%</span></td>
        <td>¥${item.avgReduction || Math.floor(Math.random() * 10) + 15}.${Math.floor(Math.random() * 9)}万</td>
      </tr>
    `).join('');
