  // 初期データの読み込みと描画
  async function loadInitialData() {
    try {
      const negotiationData = await window.aivicApi.list(0);
      const marketData = await window.aivicApi.list(1);
      const monthlyData = await window.aivicApi.list(2);

      if (negotiationData) {
        renderCustomerRanking(negotiationData.slice(0, 5));
      }
      if (monthlyData) {
        renderCategoryAnalysis(monthlyData.slice(0, 3));
        renderSalesPerformance(monthlyData.slice(0, 3));
      }

      drawSuccessTrendChart();
      drawTimingChart();
    } catch (error) {
      console.error('データ読み込みエラー:', error);
    }
  }

  // イベントリスナーの設定
  container.querySelector('#tab-success').addEventListener('click', () => switchTab('success'));
  container.querySelector('#tab-failure').addEventListener('click', () => switchTab('failure'));

  container.querySelector('#btn-analyze').addEventListener('click', async () => {
    const startDate = container.querySelector('#date-start').value;
    const endDate = container.querySelector('#date-end').value;
    const customer = container.querySelector('#customer-filter').value;
    const category = container.querySelector('#category-filter').value;
    const sales = container.querySelector('#sales-filter').value;

    // フィルター条件に基づいてデータを再取得・再描画
    try {
      const data = await window.aivicApi.list(0);
      if (data) {
        let filteredData = data;

        if (customer) {
          filteredData = filteredData.filter(item => item.顧客ID === customer);
        }
        if (category) {
          filteredData = filteredData.filter(item => item.商品カテゴリ === category);
        }
        if (sales) {
          filteredData = filteredData.filter(item => item.営業担当者ID === sales);
        }

        renderCustomerRanking(filteredData.slice(0, 5));
        drawSuccessTrendChart();
        drawTimingChart();
      }
    } catch (error) {
      console.error('分析実行エラー:', error);
    }
  });

  // 初期化
  loadInitialData();
}

