    const ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 簡易折れ線グラフ
    ctx.strokeStyle = '#22c55e';
    ctx.lineWidth = 2;
    ctx.beginPath();

    const months = ['1月', '2月', '3月', '4月', '5月', '6月'];
    const values = data.length > 0 ? data.slice(0, 6).map(d => d.発注金額合計 || 0) : [1200000, 1350000, 1180000, 1420000, 1380000, 1500000];
    const maxValue = Math.max(...values);

    values.forEach((value, i) => {
      const x = 40 + (i * 40);
      const y = 160 - (value / maxValue * 120);
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // 軸ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '10px sans-serif';
    months.forEach((month, i) => {
      ctx.fillText(month, 30 + (i * 40), 180);
    });
  }

  function drawSeasonalChart() {
    const canvas = container.querySelector('#seasonal-chart');
    const ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const centerX = 150;
    const centerY = 100;
    const radius = 60;

    // レーダーチャート背景
    ctx.strokeStyle = '#374151';
    ctx.lineWidth = 1;
    for (let i = 1; i <= 3; i++) {
      ctx.beginPath();
      ctx.arc(centerX, centerY, radius * i / 3, 0, 2 * Math.PI);
      ctx.stroke();
    }

    // 軸線
    const seasons = ['春', '夏', '秋', '冬'];
    const values = [0.8, 1.2, 0.9, 1.1];

    seasons.forEach((season, i) => {
      const angle = (i * Math.PI * 2 / 4) - Math.PI / 2;
      const x = centerX + Math.cos(angle) * radius;
      const y = centerY + Math.sin(angle) * radius;

      ctx.beginPath();
      ctx.moveTo(centerX, centerY);
      ctx.lineTo(x, y);
      ctx.stroke();

      ctx.fillStyle = '#9fb0d1';
      ctx.font = '12px sans-serif';
      ctx.fillText(season, x + Math.cos(angle) * 15 - 10, y + Math.sin(angle) * 15 + 5);
    });

    // データプロット
    ctx.strokeStyle = '#22c55e';
    ctx.fillStyle = 'rgba(34, 197, 94, 0.2)';
    ctx.lineWidth = 2;
    ctx.beginPath();

    values.forEach((value, i) => {
      const angle = (i * Math.PI * 2 / 4) - Math.PI / 2;
      const x = centerX + Math.cos(angle) * radius * value;
      const y = centerY + Math.sin(angle) * radius * value;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
  }

  function drawPriceChart(data) {
    const canvas = container.querySelector('#price-chart');
    const ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.beginPath();

    const prices = data.length > 0 ? data.slice(0, 6).map(d => d.平均発注単価 || 0) : [1200, 1180, 1220, 1150, 1190, 1160];
    const maxPrice = Math.max(...prices);
    const minPrice = Math.min(...prices);

    prices.forEach((price, i) => {
      const x = 40 + (i * 40);
      const y = 160 - ((price - minPrice) / (maxPrice - minPrice) * 120);
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    ctx.fillStyle = '#9fb0d1';
    ctx.font = '10px sans-serif';
    ctx.fillText(`¥${minPrice}`, 5, 165);
    ctx.fillText(`¥${maxPrice}`, 5, 45);
  }

  function drawCustomerChart() {
    const canvas = container.querySelector('#customer-chart');
    const ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const centerX = 150;
    const centerY = 100;
    const radius = 60;

    const customers = [
      { name: 'A社', ratio: 0.35, color: '#22c55e' },
      { name: 'B社', ratio: 0.25, color: '#3b82f6' },
      { name: 'C社', ratio: 0.20, color: '#f59e0b' },
      { name: 'その他', ratio: 0.20, color: '#6b7280' }
    ];

    let currentAngle = 0;
    customers.forEach(customer => {
      const sliceAngle = customer.ratio * 2 * Math.PI;

      ctx.fillStyle = customer.color;
      ctx.beginPath();
      ctx.moveTo(centerX, centerY);
      ctx.arc(centerX, centerY, radius, currentAngle, currentAngle + sliceAngle);
      ctx.closePath();
      ctx.fill();

      // ラベル
      const labelAngle = currentAngle + sliceAngle / 2;
      const labelX = centerX + Math.cos(labelAngle) * (radius + 20);
      const labelY = centerY + Math.sin(labelAngle) * (radius + 20);

      ctx.fillStyle = '#9fb0d1';
      ctx.font = '10px sans-serif';
      ctx.fillText(`${customer.name} ${Math.round(customer.ratio * 100)}%`, labelX - 15, labelY);

      currentAngle += sliceAngle;
    });
  }

  // KPI更新関数
  function updateKPIs(monthlyData, patternData) {
    const totalAmount = monthlyData.reduce((sum, d) => sum + (d.発注金額合計 || 0), 0);
    const avgPrice = monthlyData.length > 0 ? totalAmount / monthlyData.reduce((sum, d) => sum + (d.発注件数 || 1), 0) : 0;
    const totalOrders = monthlyData.reduce((sum, d) => sum + (d.発注件数 || 0), 0);

    container.querySelector('#total-amount').textContent = `¥${totalAmount.toLocaleString()}`;
    container.querySelector('#avg-price').textContent = `¥${Math.round(avgPrice).toLocaleString()}`;
    container.querySelector('#order-count').textContent = `${totalOrders}回`;

    // 改善余地計算
    const improvement = monthlyData.reduce((sum, d) => sum + (d.コスト削減額 || 0), 0);
    container.querySelector('#improvement').textContent = `¥${improvement.toLocaleString()}`;

    // 前月比・市場比
    if (monthlyData.length >= 2) {
      const currentMonth = monthlyData[monthlyData.length - 1];
      const prevMonth = monthlyData[monthlyData.length - 2];
      const changeRate = ((currentMonth.発注金額合計 - prevMonth.発注金額合計) / prevMonth.発注金額合計 * 100).toFixed(1);
      container.querySelector('#amount-change').textContent = `${changeRate > 0 ? '+' : ''}${changeRate}%`;

      const orderChangeRate = ((currentMonth.発注件数 - prevMonth.発注件数) / prevMonth.発注件数 * 100).toFixed(1);
      container.querySelector('#order-change').textContent = `${orderChangeRate > 0 ? '+' : ''}${orderChangeRate}%`;
    }

    if (monthlyData.length > 0) {
      const marketDiff = monthlyData[monthlyData.length - 1].市場価格との乖離率 || 0;
      container.querySelector('#market-diff').textContent = `${marketDiff > 0 ? '+' : ''}${marketDiff}%`;
    }
  }

  // 戦略提案更新関数
  function updateStrategyPanel(strategyData) {
    const panel = container.querySelector('#strategy-panel');
    if (strategyData.length === 0) {
      panel.innerHTML = '<div class="text-sm text-text-muted">戦略提案データがありません</div>';
      return;
    }

    panel.innerHTML = strategyData.map(strategy => `
      <div class="border-l-3 pl-3 py-2" style="border-left-color: #22c55e; background: var(--bg-main);">
        <div class="font-medium text-text">${strategy.商品名 || '商品名不明'}</div>
        <div class="text-sm text-text-muted mb-1">戦略区分: ${strategy.戦略区分 || '-'} | 推奨度: ${strategy.実施推奨度 || '-'}</div>
        <div class="text-sm text-text">現在単価: ¥${(strategy.現在単価 || 0).toLocaleString()} → 推奨単価: ¥${(strategy.推奨単価 || 0).toLocaleString()}</div>
        <div class="text-xs text-text-muted mt-1">${strategy.分析コメント || '詳細コメントなし'}</div>
      </div>
    `).join('');
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      const [monthlyData, patternData, strategyData] = await Promise.all([
        window.aivicApi.list(2), // 月次集計結果
        window.aivicApi.list(3), // 購買パターン分析結果
        window.aivicApi.list(4)  // 価格戦略分析結果
      ]);

      renderFrequencyTable(patternData || []);
      updateKPIs(monthlyData || [], patternData || []);
      updateStrategyPanel(strategyData || []);

      drawSalesChart(monthlyData || []);
      drawSeasonalChart();
      drawPriceChart(monthlyData || []);
      drawCustomerChart();
    } catch (error) {
      console.error('データ読み込みエラー:', error);
      renderFrequencyTable([]);
      updateKPIs([], []);
      updateStrategyPanel([]);

      drawSalesChart([]);
      drawSeasonalChart();
      drawPriceChart([]);
      drawCustomerChart();
    }
  }

  // 分析実行
  container.querySelector('#btn-analyze').addEventListener('click', async () => {
    const category = container.querySelector('#category-filter').value;
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;

    try {
      const [monthlyData, patternData, strategyData] = await Promise.all([
        window.aivicApi.list(2),
        window.aivicApi.list(3),
        window.aivicApi.list(4)
      ]);

      // フィルタリング
      let filteredMonthly = monthlyData || [];
      let filteredPattern = patternData || [];
      let filteredStrategy = strategyData || [];

      if (category) {
        filteredMonthly = filteredMonthly.filter(d => d.商品カテゴリ === category);
        filteredPattern = filteredPattern.filter(d => d.商品カテゴリ === category);
      }

      if (startDate && endDate) {
        filteredMonthly = filteredMonthly.filter(d => {
          const targetDate = d.対象年月 + '-01';
          return targetDate >= startDate && targetDate <= endDate;
        });
        filteredPattern = filteredPattern.filter(d => {
          return d.分析対象期間開始日 >= startDate && d.分析対象期間終了日 <= endDate;
        });
        filteredStrategy = filteredStrategy.filter(d => {
          return d.分析期間開始日 >= startDate && d.分析期間終了日 <= endDate;
        });
      }

      renderFrequencyTable(filteredPattern);
      updateKPIs(filteredMonthly, filteredPattern);
      updateStrategyPanel(filteredStrategy);

      drawSalesChart(filteredMonthly);
      drawSeasonalChart();
      drawPriceChart(filteredMonthly);
      drawCustomerChart();

    } catch (error) {
      console.error('分析実行エラー:', error);
    }
  });

  // 月次集計画面への遷移
  container.querySelector('#btn-monthly').addEventListener('click', () => {
    window.showScreen("scr-1780317846228");
  });

  // 初期データ読み込み実行
  loadInitialData();
}

function(container, apiUrl, tables) {
  // 1. 再描画関数の定義
  function renderComparisonRows(rows) {
    const tbody = container.querySelector("#comparison-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.分析結果ID || r.id}">
        <td class="text-xs">${r.顧客名 || "顧客名未設定"}</td>
        <td class="text-xs">${r.商品名 || "商品名未設定"}</td>
        <td class="text-xs">¥${(r.顧客単価 || 0).toLocaleString()}</td>
        <td class="text-xs">¥${(r.市場平均単価 || 0).toLocaleString()}</td>
        <td class="text-xs ${(r.市場比較率 || 0) > 0 ? 'text-red-600' : 'text-green-600'}">${(r.市場比較率 || 0) > 0 ? '+' : ''}${r.市場比較率 || 0}%</td>
        <td class="text-xs">
          <span class="px-2 py-1 rounded text-xs" style="background: ${r.価格ランク === '高価格帯' ? 'rgba(239, 68, 68, 0.1); color: #ef4444' : r.価格ランク === '低価格帯' ? 'rgba(34, 197, 94, 0.1); color: #22c55e' : 'rgba(156, 163, 175, 0.1); color: #9ca3af'};">
            ${r.価格ランク || "標準"}
          </span>
        </td>
        <td>
          <button class="action-btn secondary text-xs edit-btn" data-id="${r.分析結果ID || r.id}">詳細</button>
        </td>
      </tr>
    `).join("");
  }

  function renderNegotiationRows(rows) {
    const tbody = container.querySelector("#negotiation-tbody");
    tbody.innerHTML = rows.slice(0, 5).map(r => `
      <tr data-id="${r.交渉履歴ID || r.id}">
        <td class="text-xs">${r.交渉開始日 ? new Date(r.交渉開始日).toLocaleDateString() : "-"}</td>
        <td class="text-xs">${r.顧客名 || "顧客名未設定"}</td>
        <td class="text-xs">¥${(r.現在単価 || 0).toLocaleString()}</td>
        <td class="text-xs">¥${(r.提案単価 || 0).toLocaleString()}</td>
        <td class="text-xs">
          <span class="px-2 py-1 rounded text-xs" style="background: ${r.交渉ステータス === '合意' ? 'rgba(34, 197, 94, 0.1); color: #22c55e' : r.交渉ステータス === '交渉中' ? 'rgba(251, 191, 36, 0.1); color: #fbbf24' : 'rgba(156, 163, 175, 0.1); color: #9ca3af'};">
            ${r.交渉ステータス || "未設定"}
          </span>
        </td>
      </tr>
    `).join("");
  }

  function drawPriceTrendChart() {
    const canvas = container.querySelector("#price-trend-chart");
    const ctx = canvas.getContext("2d");

    // キャンバスサイズ調整
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * window.devicePixelRatio;
    canvas.height = rect.height * window.devicePixelRatio;
    ctx.scale(window.devicePixelRatio, window.devicePixelRatio);

    const width = rect.width;
    const height = rect.height;

    // 背景
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, width, height);

    // グリッド
    ctx.strokeStyle = '#e5e7eb';
    ctx.lineWidth = 1;

    // 縦線
    for (let i = 1; i < 6; i++) {
      const x = (width / 6) * i;
      ctx.beginPath();
      ctx.moveTo(x, 20);
      ctx.lineTo(x, height - 30);
      ctx.stroke();
    }

    // 横線
    for (let i = 1; i < 5; i++) {
      const y = 20 + ((height - 50) / 5) * i;
      ctx.beginPath();
      ctx.moveTo(40, y);
      ctx.lineTo(width - 20, y);
      ctx.stroke();
    }

    // サンプルデータ
    const customerPrices = [120000, 125000, 118000, 122000, 119000, 121000];
    const marketPrices = [115000, 116000, 117000, 118000, 119000, 120000];

    // 顧客単価線（赤）
    ctx.strokeStyle = '#ef4444';
    ctx.lineWidth = 2;
    ctx.beginPath();
    customerPrices.forEach((price, i) => {
      const x = 40 + (width - 60) * (i / (customerPrices.length - 1));
      const y = height - 30 - ((price - 115000) / 10000) * (height - 50);
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // 市場価格線（青）
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.beginPath();
    marketPrices.forEach((price, i) => {
      const x = 40 + (width - 60) * (i / (marketPrices.length - 1));
      const y = height - 30 - ((price - 115000) / 10000) * (height - 50);
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#ef4444';
    ctx.fillRect(width - 150, 30, 15, 3);
    ctx.fillStyle = '#374151';
    ctx.font = '12px sans-serif';
    ctx.fillText('顧客単価', width - 130, 38);

    ctx.fillStyle = '#3b82f6';
    ctx.fillRect(width - 150, 50, 15, 3);
    ctx.fillStyle = '#374151';
    ctx.fillText('市場価格', width - 130, 58);
  }

  // 2. 初期データ描画
  if (tables[5] && tables[5].records) {
    renderComparisonRows(tables[5].records);
  }
  if (tables[0] && tables[0].records) {
    renderNegotiationRows(tables[0].records);
  }

  // チャート描画
  setTimeout(drawPriceTrendChart, 100);

  // 3. 分析実行ボタン
  container.querySelector("#btn-analyze").addEventListener("click", async () => {
    const customerId = container.querySelector("#customer-filter").value;
    const category = container.querySelector("#category-filter").value;
    const period = container.querySelector("#analysis-period").value;

    try {
      const comparisonData = await window.aivicApi.list(5);
      const negotiationData = await window.aivicApi.list(0);

      let filteredComparison = comparisonData || [];
      let filteredNegotiation = negotiationData || [];

      if (customerId) {
        filteredComparison = filteredComparison.filter(r => r.顧客ID === customerId);
        filteredNegotiation = filteredNegotiation.filter(r => r.顧客ID === customerId);
      }

      renderComparisonRows(filteredComparison);
      renderNegotiationRows(filteredNegotiation);
      drawPriceTrendChart();

    } catch (error) {
      console.error("分析実行エラー:", error);
    }
  });

  // 4. 分析結果保存ボタン
  container.querySelector("#btn-save-analysis").addEventListener("click", async () => {
    const customerId = container.querySelector("#customer-filter").value;
    const category = container.querySelector("#category-filter").value;
    const period = container.querySelector("#analysis-period").value;

    const analysisData = {
      顧客ID: customerId || "all-customers",
      商品ID: "sample-product-001",
      分析期間開始日: period ? `${period}-01` : new Date().toISOString().split('T')[0],
      分析期間終了日: period ? `${period}-31` : new Date().toISOString().split('T')[0],
      顧客単価: 121000,
      市場平均単価: 118000,
      全顧客平均単価: 119500,
      市場比較差額: 3000,
      市場比較率: 2.5,
      全顧客比較差額: 1500,
      全顧客比較率: 1.3,
      価格ランク: "標準価格帯",
      取引数量: 150,
      取引回数: 12,
      価格改善余地: 45000,
      推奨アクション: "価格交渉",
      備考: `${period}期間の分析結果`,
      作成者: "system"
    };

    try {
      const saved = await window.aivicApi.save(5, analysisData);
      if (saved) {
        alert("分析結果を保存しました");
        const updatedData = await window.aivicApi.list(5);
        renderComparisonRows(updatedData || []);
      }
    } catch (error) {
      console.error("保存エラー:", error);
    }
  });

  // 5. CSVエクスポート
  container.querySelector("#btn-export").addEventListener("click", async () => {
    try {
      const data = await window.aivicApi.list(5);
      if (!data || data.length === 0) {
        alert("エクスポートするデータがありません");
        return;
      }

      const headers = ["顧客名", "商品名", "顧客単価", "市場平均単価", "市場比較率", "価格ランク", "推奨アクション"];
      const csvContent = "\uFEFF" + headers.join(",") + "\n" + 
        data.map(row => [
          row.顧客名 || "",
          row.商品名 || "",
          row.顧客単価 || 0,
          row.市場平均単価 || 0,
          row.市場比較率 || 0,
          row.価格ランク || "",
          row.推奨アクション || ""
        ].join(",")).join("\n");

      const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = "customer_price_analysis.csv";
      link.click();
    } catch (error) {
      console.error("エクスポートエラー:", error);
    }
  });

  // 6. 画面遷移ボタン
  container.querySelector("#btn-order-detail").addEventListener("click", () => {
    window.showScreen("scr-1780317810582");
  });

  container.querySelector("#btn-negotiation-history").addEventListener("click", () => {
    window.showScreen("scr-1780317824404");
  });

  container.querySelector("#btn-market-data").addEventListener("click", () => {
    window.showScreen("scr-1780317834607");
  });

  // 7. イベントデリゲーション（詳細ボタン）
  container.addEventListener("click", (e) => {
    const editBtn = e.target.closest(".edit-btn");
    if (editBtn) {
      const id = editBtn.dataset.id;
      alert(`分析結果ID: ${id} の詳細表示機能は今後実装予定です`);
    }
  });
}
